1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its engine,
5	// then hands off to transparent passthrough -- the ELF plus everything after
6	// `--` becomes the engine's own command line, run with inherited stdio, no
7	// timeout, and the exit code propagated, so a gdbstub / monitor / semihosting
8	// console all behave as if the engine were invoked directly. `hybrid` (F9)
9	// orchestrates a QEMU1 -> vsim handoff via run_plan and prints the window-cycle
10	// figure (the vsim mcycle delta), delimited by the marker or pc trigger.
11	#include <cstdio>
12	#include <filesystem>
13	#include <string>
14	#include <vector>
15	
16	#include "cli.hpp"
17	#include "engine_registry.hpp"
18	#include "hybrid.hpp"
19	#include "models.hpp"
20	#include "plan.hpp"
21	#include "process.hpp"
22	#include "run_passthrough.hpp"
23	#include "run_plan.hpp"
24	
25	namespace fs = std::filesystem;
26	
27	namespace andes_sim {
28	namespace {
29	
30	// Validate the lone-ELF positional shape the standalone models require: print
31	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
32	int check_one_elf(const Cli& cli, const char* model) {
33	  if (cli.positional.empty()) {
34	    std::fprintf(stderr,
35	                 "andesim run --mode %s: missing ELF (the workload to run; "
36	                 "e.g. a tests/fixtures/<name>.elf)\n",
37	                 model);
38	    return 2;
39	  }
40	  if (cli.positional.size() > 1) {
41	    std::fprintf(stderr,
42	                 "andesim run --mode %s: unexpected argument '%s' "
43	                 "(engine args go after --)\n",
44	                 model, cli.positional[1].c_str());
45	    return 2;
46	  }
47	  return 0;
48	}
49	
50	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
51	// then run the resolved engine standalone with the post-`--` args forwarded
52	// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
53	// console works unchanged) and propagating the exit code. The per-model engine
54	// + selection are resolved by the caller; `model` here only labels the
55	// positional diagnostics. This minimal slice does no ELF existence/arch
56	// validation (that lands with strict validation).
57	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
58	                   const char* model) {
59	  if (int rc = check_one_elf(cli, model)) return rc;
60	  std::string err;
61	  const std::vector<std::string> argv = passthrough_argv(
62	      eng, "standalone", cli.positional[0], cli.passthrough, err);
63	  if (!err.empty()) {
64	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
65	    return 2;
66	  }
67	  return exec_passthrough(argv);
68	}
69	
70	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
71	// the built-in qemu descriptor directly (no engine discovery -- fast needs only
72	// qemu, and discover_engines would spawn a --describe per Verilator build).
73	int run_fast(const Cli& cli) {
74	  // fast is QEMU-only; an explicit engine must name it.
75	  if (!cli.engine.empty() && cli.engine != "qemu") {
76	    std::fprintf(stderr,
77	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
78	                 cli.engine.c_str());
79	    return 2;
80	  }
81	  return run_standalone(cli, builtin_qemu(), "fast");
82	}
83	
84	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
85	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
86	// engine's own output. Unlike fast, this must discover the Verilator build(s)
87	// to resolve the engine (explicit --engine, else the sole one).
88	int run_accurate(const Cli& cli) {
89	  Discovery disc = discover_engines();
90	  std::string err;
91	  const EngineDescriptor* eng =
92	      resolve_accurate_engine(disc.engines, cli.engine, err);
93	  if (!eng) {
94	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
95	    // Surface why an expected engine may be absent (failed --describe, etc.).
96	    for (const std::string& w : disc.warnings)
97	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
98	    return 2;
99	  }
100	  return run_standalone(cli, *eng, "cycle");
101	}
102	
103	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
104	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle figure
105	// is the vsim mcycle minus QEMU1's drained mcycle. This slice builds the 2-step
106	// plan and runs it; the exact per-leg dry-run command lines, --mem-size, and
107	// --verify land as the feature grows.
108	int run_hybrid(const Cli& cli) {
109	  auto fail = [](const std::string& msg) {
110	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
111	    return 2;
112	  };
113	
114	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
115	  const std::string elf = cli.positional[0];
116	
117	  std::string err;
118	  const Trigger trig = hybrid_trigger(cli, elf, err);
119	  if (!err.empty()) return fail(err);
120	
121	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
122	  // or the sole cycle-accurate engine (reusing the F8 selector).
123	  Discovery disc = discover_engines();
124	  const EngineDescriptor* acc =
125	      resolve_accurate_engine(disc.engines, cli.engine, err);
126	  if (!acc) {
127	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
128	    for (const std::string& w : disc.warnings)
129	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
130	    return 2;
131	  }
132	
133	  Plan plan;
134	  plan.elf = elf;
135	  plan.mem_size = 128LL * 1024 * 1024;  // shared mmap; --mem-size lands later
136	  plan.steps = {
137	      Step{"qemu", "fast-leg", trig},
138	      Step{acc->id, "accurate-leg", trig},
139	  };
140	
141	  // Banner to stderr so the window-cycle result stands alone on stdout.
142	  const std::string fixture = fs::path(elf).stem().string();
143	  std::fprintf(stderr, "[andesim] model=hybrid engine=%s trigger=%s fixture=%s\n",
144	               acc->id.c_str(), trig.kind.c_str(), fixture.c_str());
145	
146	  // --dry-run: report the 2-step plan and spawn nothing. The exact per-leg
147	  // command lines land with the dry-run print feature; here we confirm the
148	  // plan the handoff would run.
149	  if (cli.dry_run) {
150	    std::printf("[andesim] dry-run: %zu-step plan (spawns nothing)\n",
151	                plan.steps.size());
152	    for (size_t i = 0; i < plan.steps.size(); ++i)
153	      std::printf("# step %zu/%zu: %s [%s]\n", i + 1, plan.steps.size(),
154	                  plan.steps[i].role.c_str(), plan.steps[i].engine_id.c_str());
155	    return 0;
156	  }
157	
158	  const PlanResult r = run_plan(plan, disc.engines);
159	  if (!r.ok()) {
160	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
161	    return 1;
162	  }
163	  // phases[0] = QEMU1 drain, [1] = vsim drain; the window figure is the vsim
164	  // mcycle delta.
165	  const unsigned long long q_mc = r.phases[0].mcycle;
166	  const unsigned long long v_mc = r.phases[1].mcycle;
167	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
168	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
169	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
170	              fixture.c_str());
171	  return 0;
172	}
173	
174	}  // namespace
175	
176	int cmd_run(const Cli& cli) {
177	  if (cli.model.empty()) {
178	    std::fprintf(stderr,
179	                 "andesim run: --mode fast|cycle|hybrid is required "
180	                 "(pick the composition; see 'andesim run --help')\n");
181	    return 2;
182	  }
183	  if (!find_model(cli.model)) {
184	    std::fprintf(stderr,
185	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
186	                 cli.model.c_str());
187	    return 2;
188	  }
189	  if (cli.model == "fast") return run_fast(cli);
190	  if (cli.model == "cycle") return run_accurate(cli);
191	  return run_hybrid(cli);  // model validated above; only hybrid remains
192	}
193	
194	}  // namespace andes_sim
