21	// The bundled functional engine. QEMU does not implement --describe, so its
22	// descriptor is built in. Binary path honors $VSIM_QEMU (the explicit binary),
23	// then $QEMU_BIN_DIR (env or config.env), then the legacy in-tree build.
24	EngineDescriptor builtin_qemu() {
25	  EngineDescriptor d;
26	  d.id = "qemu";
27	  d.type = "qemu";
28	  d.kind = "functional";
29	  d.xlen = 64;
30	  d.triggers = {"marker", "pc"};
31	  d.roles = {"standalone", "fast-leg"};
32	  d.state = {"drain"};
33	  d.source = "built-in";
34	  // The standalone functional run (model=fast): the andes machine + a concrete
35	  // vector-capable core (the generic default -cpu hangs the fixtures), no shared
36	  // mmap and no plugin. run_passthrough fills {bin}/{elf}; the user's post-`--`
37	  // args (gdbstub, monitor, ...) append after.
38	  d.invoke.push_back(
39	      {"standalone",
40	       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
41	        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
42	        "{elf}"}});
43	  // The hybrid fast-forward leg (model=hybrid): load the ELF onto the shared
44	  // mmap backend, drain on the plugin's marker trigger into {state_out}, exit
45	  // 200. {mmap}/{mmap_size}/{plugin}/{state_out} are filled by the plan
46	  // executor (F6).
47	  d.invoke.push_back(
48	      {"fast-leg",
49	       {"{bin}", "-object",
50	        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
51	        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
52	        "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
53	        "enable=on,target=native", "-bios", "{elf}", "-plugin",
54	        "{plugin},outfile={state_out}"}});
55	  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
56	    d.bin_path = q;
57	  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
58	    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
59	  else
60	    d.bin_path = (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
61	  return d;
62	}
