input.new_string:
const EngineDescriptor q = builtin_qemu();
CHECK(q.id == "qemu");
CHECK(q.type == "qemu");
CHECK(q.kind == "functional");
CHECK(q.xlen == 64);

// --- model=fast default cpu: a concrete vector-capable andes core ---
// andes_ae350's generic default -cpu hangs the vplat fixtures, so fast pins the
// vector-capable andes-ax46mpv. andesim passes NO vlen -- the cpu model's own
// QEMU default applies, so both scalar and vector binaries run out of the box;
// a user who wants a specific width passes it via the post-`--` -cpu (which
// still wins).
auto fast_cpu = [](const EngineDescriptor& e) -> std::string {
  const std::vector<std::string>* st = e.invoke_for("standalone");
  if (!st) return "";
  for (std::size_t i = 0; i + 1 < st->size(); ++i)
    if ((*st)[i] == "-cpu") return (*st)[i + 1];
  return "";
};
CHECK(fast_cpu(q) == "andes-ax46mpv");

// --- resolve_accurate_engine rejection is mode-agnostic ---
// It serves BOTH --mode cycle and --mode hybrid, so its rejection of a
// functional engine must not hardcode "model cycle" (the caller already
// prefixes "andesim run --mode <mode>:").
{
  const std::vector<EngineDescriptor> engs = {q};  // qemu is functional
  std::string err;
  CHECK(resolve_accurate_engine(engs, "qemu", err) == nullptr);
  CHECK(err.find("functional") != std::string::npos);
  CHECK(err.find("cycle-accurate") != std::string::npos);
  CHECK(err.find("model cycle") == std::string::npos);
}

